import (
	"fmt"
)

resp, err := client.TaxZones().ListTaxZones(ctx, map[string]any{"limit": 2}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["tax_zones"].([]any) {
	zone := row.(map[string]any)
	fmt.Println(zone["id"], zone["name"], zone["system_generated"])
}

